        std::fs::write(&a, b"").unwrap();
        std::fs::write(&b, b"").unwrap();
        assert!(same_contents(&a, &b).unwrap());
        assert!(same_contents(&a, &dir.join("missing")).is_err());
        let _ = std::fs::remove_dir_all(&dir);
    }

